  "source": "\"Implement LRU/LFU cache with custom eviction\" appears in Citadel interview reports, and LRU cache shows up in 2026 Meta reports.",
  "starter": "class LRUCache:\n    def __init__(self, capacity):\n        pass\n\n    def get(self, key):\n        pass\n\n    def put(self, key, value):\n        pass",
  "reference": "from collections import OrderedDict, defaultdict\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.cap = capacity\n        self.d = OrderedDict()\n\n    def get(self, key):\n        if key not in self.d:\n            return -1\n        self.d.move_to_end(key)\n        return self.d[key]\n\n    def put(self, key, value):\n        if self.cap <= 0:\n            return\n        if key in self.d:\n            self.d.move_to_end(key)\n        self.d[key] = value\n        if len(self.d) > self.cap:\n            self.d.popitem(last=False)\n\nclass LFUCache:\n    def __init__(self, capacity):\n        self.cap = capacity\n        self.val = {}\n        self.freq = {}\n        self.buckets = defaultdict(OrderedDict)   # freq -> keys in LRU order\n        self.minf = 0\n\n    def _touch(self, key):\n        f = self.freq[key]\n        del self.buckets[f][key]\n        if not self.buckets[f]:\n            del self.buckets[f]\n            if self.minf == f:\n                self.minf = f + 1\n        self.freq[key] = f + 1\n        self.buckets[f + 1][key] = None\n\n    def get(self, key):\n        if key not in self.val:\n            return -1\n        self._touch(key)\n        return self.val[key]\n\n    def put(self, key, value):\n        if self.cap <= 0:\n            return\n        if key in self.val:\n            self.val[key] = value\n            self._touch(key)\n            return\n        if len(self.val) >= self.cap:\n            old, _ = self.buckets[self.minf].popitem(last=False)\n            if not self.buckets[self.minf]:\n                del self.buckets[self.minf]\n            del self.val[old], self.freq[old]\n        self.val[key] = value\n        self.freq[key] = 1\n        self.buckets[1][key] = None\n        self.minf = 1",
