  "reference": "from collections import deque, defaultdict\n\nclass HitCounter:\n    def __init__(self):\n        self.q = deque()\n\n    def hit(self, timestamp):\n        self.q.append(timestamp)\n\n    def get_hits(self, timestamp):\n        while self.q and self.q[0] <= timestamp - 300:\n            self.q.popleft()\n        return len(self.q)\n\nclass RateLimiter:\n    def __init__(self, limit, window):\n        self.limit, self.window = limit, window\n        self.log = defaultdict(deque)\n\n    def allow(self, user, t):\n        q = self.log[user]\n        while q and q[0] <= t - self.window:\n            q.popleft()\n        if len(q) < self.limit:\n            q.append(t)\n            return True\n        return False\n\nclass TokenBucket:\n    def __init__(self, capacity, rate):\n        self.cap, self.rate = capacity, rate\n        self.tokens = float(capacity)\n        self.last = None\n\n    def allow(self, t, cost=1):\n        if self.last is not None:\n            self.tokens = min(self.cap, self.tokens + (t - self.last) * self.rate)\n        self.last = t\n        if self.tokens >= cost:\n            self.tokens -= cost\n            return True\n        return False",
