  "starter": "def is_balanced(s):\n    pass",
  "reference": "PAIRS = {')': '(', ']': '[', '}': '{'}\n\ndef _scan(s):\n    stack = []\n    for i, ch in enumerate(s):\n        if ch in '([{':\n            stack.append(i)\n        elif ch in PAIRS:\n            if not stack or s[stack[-1]] != PAIRS[ch]:\n                return i, stack, []\n            stack.pop()\n    return -1, stack, None\n\ndef is_balanced(s):\n    bad, stack, _ = _scan(s)\n    return bad == -1 and not stack\n\ndef first_error(s):\n    bad, stack, _ = _scan(s)\n    if bad != -1:\n        return bad\n    return stack[0] if stack else -1\n\ndef match_pairs(s):\n    if not is_balanced(s):\n        return []\n    stack, out = [], []\n    for i, ch in enumerate(s):\n        if ch in '([{':\n            stack.append(i)\n        elif ch in PAIRS:\n            out.append([stack.pop(), i])\n    return sorted(out)",
