  "reference": "def encode(s):\n    out = []\n    for ch in s:\n        if out and out[-1][0] == ch:\n            out[-1][1] += 1\n        else:\n            out.append([ch, 1])\n    return out\n\ndef decode(runs):\n    return ''.join(ch * n for ch, n in runs)\n\nclass StreamEncoder:\n    def __init__(self):\n        self.cur = None     # the run that might still grow\n\n    def feed(self, chunk):\n        done = []\n        for ch in chunk:\n            if self.cur and self.cur[0] == ch:\n                self.cur[1] += 1\n            else:\n                if self.cur:\n                    done.append(self.cur)\n                self.cur = [ch, 1]\n        return done\n\n    def flush(self):\n        out = [self.cur] if self.cur else []\n        self.cur = None\n        return out",
